// Class 6 Social Science practice bank, part 1: Locating Places on the Earth to India's Cultural Roots (Exploring Society: India and Beyond).
StudyData.addPractice(6, "sst", {
  "locating-places-on-earth": {
    mcq: [
      { q: "A globe shows the Earth more accurately than a flat map because the Earth is shaped like a", options: ["cube", "cylinder", "sphere", "flat disc"], answer: 2, explain: "The Earth is a sphere, and a globe is a small model of that shape. A flat map has to stretch or squeeze some parts.", level: 1 },
      { q: "At what latitude is the North Pole?", options: ["0°", "45°N", "90°S", "90°N"], answer: 3, explain: "The equator is 0° and the North Pole is 90°N. The South Pole is 90°S.", level: 1 },
      { q: "Which imaginary line passes through Greenwich, near London?", options: ["The equator", "The Prime Meridian", "The Tropic of Cancer", "The Tropic of Capricorn"], answer: 1, explain: "The Prime Meridian (0° longitude) passes through Greenwich. The other lines are lines of latitude.", level: 1 },
      { q: "What does the legend (key) of a map tell us?", options: ["The meaning of the symbols and colours used", "The year in which the map was printed", "The height of the map-maker", "The direction in which rivers flow"], answer: 0, explain: "The legend explains the symbols and colours used on a map so that we can read it correctly.", level: 1 },
      { q: "Lines of latitude measure the distance of a place", options: ["east or west of the Prime Meridian", "above or below the sea level", "from Greenwich to the equator", "north or south of the equator"], answer: 3, explain: "Latitudes measure distance north or south of the equator. Longitudes measure distance east or west of the Prime Meridian.", level: 1 },
      { q: "Place A is at 30°E and place B is at 40°E. Which place sees the sun earlier, and by how much?", options: ["A, by 40 minutes", "B, by 40 minutes", "B, by 10 minutes", "A, by 2 hours 40 minutes"], answer: 1, explain: "B is further east, so it sees the sun first. The difference is 10°, and 10 × 4 minutes = 40 minutes.", level: 2 },
      { q: "When it is 12 noon at Greenwich (GMT), what is the Indian Standard Time?", options: ["6:30 p.m.", "7:00 p.m.", "5:30 p.m.", "5:30 a.m."], answer: 2, explain: "IST is 5 hours 30 minutes ahead of GMT, so noon at Greenwich is 5:30 p.m. in India. (India is east of Greenwich, so its time is ahead, not behind.)", level: 2 },
      { q: "Through how many degrees does the Earth turn in 4 hours?", options: ["15°", "60°", "75°", "96°"], answer: 1, explain: "The Earth turns 15° every hour, so in 4 hours it turns 4 × 15° = 60°.", level: 2 },
      { q: "Ria follows a line of longitude on a globe, moving upwards, until she cannot go any further.\nWhere does she finish?", options: ["On the equator", "On the Tropic of Cancer", "On the Prime Meridian", "At the North Pole"], answer: 3, explain: "Lines of longitude run from pole to pole, so going up along one ends at the North Pole, where all the longitudes meet.", level: 2 },
      { q: "Assertion (A): A globe is a better model of the Earth than a flat map.\nReason (R): The Earth is a sphere.", options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."], answer: 0, explain: "Both statements are true. A globe is also a sphere, so it shows the real shape of the Earth. This is why R explains A.", level: 2, keepOrder: true },
      { q: "When it is 10 a.m. on India's standard meridian (82°30′E), what is the local time at a place on 22°30′E?", options: ["2 p.m.", "6 a.m.", "7 a.m.", "10 p.m."], answer: 1, explain: "The difference in longitude is 82°30′ − 22°30′ = 60°. That is 60 × 4 = 240 minutes = 4 hours. The place is to the west, so its time is behind: 10 a.m. − 4 hours = 6 a.m.", level: 3 },
      { q: "It is noon at place Y. Place X is 10° east of Y.\nWhat is the local time at X?", options: ["11:20 a.m.", "12:10 p.m.", "12:40 p.m.", "2:30 p.m."], answer: 2, explain: "10° × 4 minutes = 40 minutes. X is east, so its time is ahead: 12:40 p.m.", level: 3 },
      { q: "Through how many degrees does the Earth turn in 6 hours 20 minutes?", options: ["95°", "90°", "100°", "105°"], answer: 0, explain: "In 6 hours it turns 6 × 15° = 90°. In 20 minutes it turns 20 ÷ 4 = 5°. The total is 95°.", level: 3 },
      { q: "A traveller stands exactly at the North Pole and starts to walk in any direction she likes.\nIn which direction is she walking?", options: ["East", "West", "North", "South"], answer: 3, explain: "The North Pole is the northernmost point, so every direction from it leads away from the pole, which is south. This is why all lines of longitude meet there.", level: 3 }
    ],
    written: [
      { q: "Define latitude.", a: "Latitudes are imaginary lines that run east to west, parallel to each other, and measure the distance of a place north or south of the equator.", marks: 1 },
      { q: "Which line is called the Prime Meridian? What is its value?", a: "The imaginary line of longitude that passes through Greenwich, near London, is the Prime Meridian. Its value is 0°.", marks: 1 },
      { q: "Write two differences between lines of latitude and lines of longitude.", a: "1. Latitudes run east to west and are parallel to each other; longitudes run from the North Pole to the South Pole and meet at the poles.\n2. Latitudes measure distance north or south of the equator (0°); longitudes measure distance east or west of the Prime Meridian (0°).", marks: 2 },
      { q: "The Earth turns 15° every hour. How many degrees does it turn in 8 hours? How many minutes of time does 1° of longitude make?", a: "In 8 hours the Earth turns 8 × 15° = 120°.\nIt takes 60 minutes to turn 15°, so 1° takes 60 ÷ 15 = 4 minutes.", marks: 2 },
      { q: "Why is it useful for a large country like India to have one standard time?", a: "1. One time makes timetables of trains, flights, schools and offices the same everywhere, which avoids confusion.\n2. Everyone in the country can fix meetings and broadcasts using the same clock (IST, based on the 82°30′E meridian).", marks: 2 },
      { q: "Place P is 30° east of place Q. When it is 9:00 a.m. at Q, what is the time at P? Show your steps.", a: "Difference in longitude = 30°.\nTime difference = 30 × 4 minutes = 120 minutes = 2 hours.\nP is to the east, so its time is ahead of Q's.\nTime at P = 9:00 a.m. + 2 hours = 11:00 a.m.", marks: 3 },
      { q: "Describe the location of India using the grid of latitudes and longitudes.", a: "1. India lies roughly between 8°4′N and 37°6′N latitude, so it is entirely north of the equator.\n2. It lies roughly between 68°7′E and 97°25′E longitude, so it is east of the Prime Meridian.\n3. The Tropic of Cancer (23½°N) passes through the middle of India, and the standard meridian 82°30′E is used for IST.", marks: 3 },
      { q: "Case study: Nisha looks at a globe. The lines that run around the globe from east to west never touch each other. The lines that run from the top to the bottom all meet at the top and at the bottom. A thick line around the middle of the globe is marked 0°.\n(i) What are the lines that never touch each other called?\n(ii) Where do the top-to-bottom lines meet?\n(iii) What is the thick line marked 0° around the middle called?", a: "(i) They are lines of latitude (parallels).\n(ii) They meet at the North Pole and the South Pole.\n(iii) It is the equator, the 0° line of latitude.", marks: 4, type: "case" }
    ]
  },
  "oceans-and-continents": {
    mcq: [
      { q: "Which ocean is named after our country?", options: ["Pacific Ocean", "Indian Ocean", "Atlantic Ocean", "Arctic Ocean"], answer: 1, explain: "The Indian Ocean gets its name from India, and it touches India's southern coast.", level: 1 },
      { q: "Which continent is the coldest and is covered by thick ice?", options: ["Europe", "Africa", "Antarctica", "Australia"], answer: 2, explain: "Antarctica is the coldest continent and is covered by a thick sheet of ice.", level: 1 },
      { q: "About what share of the Earth's surface is land?", options: ["29%", "71%", "50%", "10%"], answer: 0, explain: "About 71% of the surface is water, so the remaining 29% is land.", level: 1 },
      { q: "India lies in the southern part of which continent?", options: ["Africa", "Europe", "Australia", "Asia"], answer: 3, explain: "India lies in the southern part of Asia, the largest continent.", level: 1 },
      { q: "How many oceans are there on the Earth?", options: ["Three", "Five", "Seven", "Four"], answer: 1, explain: "There are five oceans: the Pacific, Atlantic, Indian, Arctic and Southern. (Seven is the number of continents.)", level: 1 },
      { q: "A ship sails south from the southern tip of India. Which ocean does it sail through first?", options: ["Pacific Ocean", "Arctic Ocean", "Atlantic Ocean", "Indian Ocean"], answer: 3, explain: "India's southern coast is touched by the Indian Ocean, so a ship going south enters it first.", level: 2 },
      { q: "Dev looks at a globe and sees that the east coast of South America and the west coast of Africa have shapes that seem to fit together like pieces of a jigsaw.\nWhich idea does this support?", options: ["The continents were once joined and have drifted apart", "The Earth is flat", "The oceans have always been the same size", "Continents never move"], answer: 0, explain: "The matching coastlines support Wegener's idea that the continents were once joined in Pangaea and later drifted apart.", level: 2 },
      { q: "A student spins a globe and stops it with a finger at a random spot.\nWhere is the finger more likely to land?", options: ["On land, because land is the larger part", "Land and water are equally likely", "On water, because water covers about 71% of the surface", "It cannot be said"], answer: 2, explain: "Since about 71% of the surface is water and only 29% is land, the finger is more likely to land on water.", level: 2 },
      { q: "Assertion (A): The Himalayas are still rising.\nReason (R): The Indian plate is still pushing against the Eurasian plate.", options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."], answer: 0, explain: "The Himalayas were pushed up when the Indian plate collided with the Eurasian plate, and the continued push keeps raising them. So R explains A.", level: 2, keepOrder: true },
      { q: "Which one of these is NOT a continent?", options: ["Arctic", "Europe", "Antarctica", "Africa"], answer: 0, explain: "The Arctic is an ocean. Europe, Antarctica and Africa are continents.", level: 2 },
      { q: "Which list contains only oceans?", options: ["Atlantic, Red, Indian, Southern", "Pacific, Atlantic, Arctic, Southern", "Indian, Bay of Bengal, Pacific, Arctic", "Pacific, Arabian, Indian, Atlantic"], answer: 1, explain: "The Pacific, Atlantic, Arctic and Southern are all oceans. The Red Sea, the Bay of Bengal and the Arabian Sea are smaller water bodies, not oceans.", level: 3 },
      { q: "Rocks and fossils of the same kind of land animal are found on continents that are now separated by wide oceans.\nWhich is the best explanation?", options: ["Land animals can swim across any ocean", "The oceans are slowly drying up", "Continents never move, so the animals walked on the sea floor", "The continents were once joined as one landmass and later drifted apart"], answer: 3, explain: "If the continents were once joined as Pangaea, the animals could live across the whole landmass. As the continents drifted apart, the fossils ended up on separate continents.", level: 3 },
      { q: "Which statement about the Indian plate is correct?", options: ["It moved south and formed the Himalayas", "It moved west and joined Africa", "It moved north, collided with the Eurasian plate and pushed up the Himalayas", "It is the plate on which the Pacific Ocean lies"], answer: 2, explain: "The Indian plate moved north and collided with the Eurasian plate. The land was pushed up to form the Himalayas.", level: 3 },
      { q: "Which pair of continents are both crossed by the equator?", options: ["Europe and Antarctica", "Africa and South America", "Australia and Europe", "North America and Antarctica"], answer: 1, explain: "The equator passes through Africa and South America (and parts of Asia). It does not pass through Europe, Antarctica or North America.", level: 3 }
    ],
    written: [
      { q: "Name the five oceans of the world.", a: "The five oceans are the Pacific, Atlantic, Indian, Arctic and Southern (Antarctic) oceans.", marks: 1 },
      { q: "What is Pangaea?", a: "Pangaea is the name given by Alfred Wegener to the single huge landmass in which all the continents were once joined together.", marks: 1 },
      { q: "State two facts about Antarctica.", a: "1. Antarctica is the coldest continent.\n2. It is covered by thick ice.", marks: 2 },
      { q: "What is continental drift? Name the scientist who proposed that the continents were once joined.", a: "Continental drift is the very slow movement of the continents over millions of years.\nThe German scientist Alfred Wegener proposed that all the continents were once joined together.", marks: 2 },
      { q: "Write two facts about the Indian Ocean.", a: "1. It touches the southern coast of India.\n2. It gets its name from India.", marks: 2 },
      { q: "Explain the idea of Pangaea and what happened to it.", a: "1. Alfred Wegener proposed that long ago all the continents formed one huge landmass called Pangaea.\n2. This landmass slowly broke up and the pieces moved apart.\n3. The continents are still moving slowly today, which is called continental drift.", marks: 3 },
      { q: "List the seven continents. Name the largest and the smallest of them.", a: "The seven continents are Asia, Africa, North America, South America, Antarctica, Europe and Australia.\nAsia is the largest continent.\nAustralia is the smallest continent.", marks: 3 },
      { q: "Case study: A teacher spins a globe and shows how much of it is blue. She says that about 71% of the Earth's surface is covered with water. She then points to a huge, ice-covered continent at the bottom of the globe, and to the ocean that touches the southern coast of India.\n(i) What percentage of the Earth's surface is land?\n(ii) Name the continent covered with thick ice.\n(iii) Name the ocean that touches the southern coast of India.", a: "(i) 100% − 71% = 29% is land.\n(ii) Antarctica.\n(iii) The Indian Ocean.", marks: 4, type: "case" }
    ]
  },
  "landforms-and-life": {
    mcq: [
      { q: "Which landform is a wide, low and flat area of land?", options: ["Plateau", "Mountain", "Plain", "Hill"], answer: 2, explain: "A plain is wide, low and flat. A plateau is raised land with a flat top, and mountains are very high with steep slopes.", level: 1 },
      { q: "The Ganga and the Brahmaputra begin in which landform region?", options: ["Thar Desert", "Himalayas", "Deccan Plateau", "Indo-Gangetic Plain"], answer: 1, explain: "These rivers begin in the Himalayas, where snow and glaciers melt and feed them.", level: 1 },
      { q: "The black soil of the Deccan Plateau is especially good for growing", options: ["cotton", "apples", "tea", "jute"], answer: 0, explain: "The black soil of the Deccan Plateau suits cotton.", level: 1 },
      { q: "Which animals are commonly reared by people in desert areas with little rain?", options: ["Dolphins", "Penguins", "Camels and goats", "Polar bears"], answer: 2, explain: "Camels, goats and sheep are kept in deserts. Dolphins live in water and penguins and polar bears live in cold regions.", level: 1 },
      { q: "People who live along coasts and on islands often depend on", options: ["terrace farming", "growing apples on hills", "herding camels", "fishing"], answer: 3, explain: "Coastal and island people often get food and income from fishing.", level: 1 },
      { q: "Why have so many towns and villages grown on the Indo-Gangetic Plain?", options: ["It is the highest land in India", "It is flat and fertile, and rivers bring water to it", "It receives no rain at all", "It is covered with snow"], answer: 1, explain: "Flat, fertile land with water from rivers makes farming and settling easy, so many people live there.", level: 2 },
      { q: "Assertion (A): The Ganga begins in the Himalayas.\nReason (R): The Himalayas are fold mountains.", options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."], answer: 1, explain: "Both are true. But the Ganga begins there because snow and glaciers melt and feed it, not because the Himalayas are fold mountains. So R does not explain A.", level: 2, keepOrder: true },
      { q: "Harpreet's family has a farm on a steep hillside where crops cannot grow well on the slope.\nWhat can they do?", options: ["Cut flat steps (terraces) into the slope", "Wait for the hill to turn into a plain", "Grow their crops on the snow", "Move the soil into the sea"], answer: 0, explain: "Terraces are flat steps cut into the hillside. They make flat land on which crops can be grown.", level: 2 },
      { q: "Imran's uncle lives in a desert area where it rarely rains.\nWhich work is most suitable for him there?", options: ["Growing paddy in large flooded fields", "Deep-sea fishing", "Terrace farming of tea", "Rearing camels, goats and sheep"], answer: 3, explain: "Very little rain makes crop farming hard, so people in deserts often keep animals such as camels, goats and sheep.", level: 2 },
      { q: "What happens to land over a very long time because of weathering and erosion?", options: ["It never changes", "Plateaus turn into oceans", "It is worn down and its shape changes", "It is folded up into mountains"], answer: 2, explain: "Weathering and erosion slowly wear the land down and change its shape. Folding is a different process.", level: 2 },
      { q: "Which pair correctly matches a landform with an example from India?", options: ["Fold mountains – Himalayas", "Plain – Thar Desert", "Plateau – Ganga river", "Fold mountains – Deccan"], answer: 0, explain: "The Himalayas are fold mountains. The Deccan is a plateau, the Indo-Gangetic region is a plain, and the Ganga is a river.", level: 3 },
      { q: "A group wants to build a new town. Which place is the best choice, and why?", options: ["A steep mountain slope, because it is high", "A snow-covered peak, because it has water", "A flat plain near a river, because land is flat and fertile and water is available", "The middle of a desert, because land is open"], answer: 2, explain: "A flat plain near a river makes building, farming and getting water easy, which is why many towns grow on plains.", level: 3 },
      { q: "Which sequence correctly shows how a landform can shape life?", options: ["Many towns grow, then farming begins, then the soil becomes fertile", "River silt makes the soil fertile, farming becomes easy, villages and towns grow", "Towns grow, then the river brings silt, then soil gets fertile", "Farming ends, villages disappear, the plain becomes a mountain"], answer: 1, explain: "On a plain, rivers bring silt that makes soil fertile, farming becomes easy, and so villages and towns grow. The other sequences put the steps in the wrong order.", level: 3 },
      { q: "Village A is on a fertile plain by a river. Village B is on a steep mountain slope.\nWhich statement is correct?", options: ["Both villages farm in exactly the same way", "Village A must cut terraces, while Village B can farm on flat land", "Neither village can farm", "Village A can farm on flat land easily, while Village B may need terraces"], answer: 3, explain: "The plain has flat, fertile land. The steep slope needs terraces, which are flat steps, to grow crops.", level: 3 }
    ],
    written: [
      { q: "Define a plateau.", a: "A plateau is a large area of raised land with a mostly flat top and steep sides.", marks: 1 },
      { q: "What are terraces?", a: "Terraces are flat steps cut into hill slopes so that crops can be grown on the otherwise steep land.", marks: 1 },
      { q: "Why do many towns and villages grow on the Indo-Gangetic Plain?", a: "1. The plain is flat and the soil is very fertile, so farming is easy.\n2. Rivers bring water and fresh soil to the plain, so many people settle there and towns grow.", marks: 2 },
      { q: "Name any four natural forces that shape landforms.", a: "Landforms are shaped by the movement of the Earth's plates, rivers, wind, glaciers and volcanoes (any four).", marks: 2 },
      { q: "Why do people in desert areas often keep animals such as camels, goats and sheep?", a: "1. Deserts get very little rain, so growing crops is difficult.\n2. People therefore depend on animals such as camels, goats and sheep for their living.", marks: 2 },
      { q: "Describe, with three examples, how landforms affect the way people live.", a: "1. In hilly areas, people cut terraces on the slopes to grow crops.\n2. In deserts, where there is little rain, people often keep camels, goats and sheep.\n3. People on coasts and islands often depend on fishing for food and income.", marks: 3 },
      { q: "Write three features of the Himalayas.", a: "1. The Himalayas are young fold mountains, formed when the Earth's crust was folded up.\n2. They are among the highest mountains in the world.\n3. Rivers such as the Ganga and the Brahmaputra begin there, fed by melting snow and glaciers.", marks: 3 },
      { q: "Case study: Gurmeet visits a hill village where small flat fields climb up the hillside like steps. On the way he passes a wide, low and flat river valley with green fields and many towns. Later he sees a flat-topped raised region with black soil, where cotton is grown.\n(i) What are the flat steps cut into the hill slopes called?\n(ii) Which landform is the wide, low, flat land with many towns?\n(iii) Name the plateau of peninsular India that has black soil good for cotton.", a: "(i) Terraces.\n(ii) A plain, for example the Indo-Gangetic Plain.\n(iii) The Deccan Plateau.", marks: 4, type: "case" }
    ]
  },
  "timeline-and-sources-of-history": {
    mcq: [
      { q: "Which of these years is the earliest in time?", options: ["100 CE", "50 BCE", "300 BCE", "10 CE"], answer: 2, explain: "BCE years count backwards, so 300 BCE is further in the past than 50 BCE. All the CE years come after the BCE years.", level: 1 },
      { q: "A millennium is a period of", options: ["1000 years", "100 years", "10 years", "500 years"], answer: 0, explain: "A millennium is 1000 years. A century is 100 years.", level: 1 },
      { q: "Words carved on stone or metal are called", options: ["timelines", "excavations", "legends", "inscriptions"], answer: 3, explain: "Inscriptions are words carved on stone or metal. They often give names of rulers and dates.", level: 1 },
      { q: "Digging carefully in the ground to find remains of the past is called", options: ["erosion", "excavation", "migration", "inscription"], answer: 1, explain: "Excavation is the careful digging of old sites. It brings out tools, pots, coins and other remains.", level: 1 },
      { q: "Which of these is an archaeological source?", options: ["The Vedas", "A coin found in a field", "A song sung by elders", "A story told by a grandmother"], answer: 1, explain: "A coin is an object found through digging, so it is an archaeological source. The Vedas are written, and songs and stories told aloud are oral.", level: 1 },
      { q: "How many years are there from 500 BCE to 200 BCE?", options: ["200 years", "700 years", "300 years", "500 years"], answer: 2, explain: "Both years are BCE, so subtract: 500 − 200 = 300 years. (Adding would give 700, which is wrong because BCE years count backwards.)", level: 2 },
      { q: "Why do historians ask who wrote a source and why?", options: ["To make all sources look the same", "To decide which sources to throw away without reading them", "To find out how old the writer was", "To find out whether the source may be biased"], answer: 3, explain: "A writer may show only one side. Knowing who wrote it and why helps a historian judge how reliable it is.", level: 2 },
      { q: "Assertion (A): Prehistory is the period for which we have no written records.\nReason (R): Writing had not yet been invented in that period.", options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."], answer: 0, explain: "Prehistory is the time before writing. Because nobody could write, there are no written records, so R explains A.", level: 2, keepOrder: true },
      { q: "A farmer digging for a well finds old clay pots and a coin.\nWhat kind of source has he found?", options: ["Oral source", "Archaeological source", "Literary source", "Biased source"], answer: 1, explain: "Pots and coins found in the ground are objects of the past, so they are archaeological sources.", level: 2 },
      { q: "Gurleen's grandmother sings a song that she learnt from her own grandmother.\nWhat kind of source is this song?", options: ["Archaeological source", "Literary source", "Oral source", "Inscription"], answer: 2, explain: "A song passed from one generation to the next by speaking and singing is an oral source.", level: 2 },
      { q: "Which sources would best tell a historian the name of a ruler and the date of his rule?", options: ["Rock paintings of the Stone Age", "Animal bones", "Stone tools", "Inscriptions and coins"], answer: 3, explain: "Inscriptions and coins often carry the names of rulers and dates.", level: 3 },
      { q: "A royal record says that the king won every battle he fought.\nWhat should a historian do?", options: ["Check who wrote it and why, and compare it with other sources", "Accept every word as true", "Ignore all records", "Use only this record and no other"], answer: 0, explain: "A royal record may be biased in favour of the king. Comparing it with other sources gives a more reliable picture.", level: 3 },
      { q: "Four events took place in 600 BCE, 200 BCE, 100 CE and 700 BCE.\nWhich is the correct order from earliest to latest?", options: ["100 CE, 200 BCE, 600 BCE, 700 BCE", "600 BCE, 700 BCE, 200 BCE, 100 CE", "700 BCE, 600 BCE, 200 BCE, 100 CE", "200 BCE, 600 BCE, 700 BCE, 100 CE"], answer: 2, explain: "BCE years count backwards, so 700 BCE is the earliest, then 600 BCE, then 200 BCE. The CE year, 100 CE, comes last.", level: 3 },
      { q: "The year 2025 CE is how many centuries after the year 25 CE?", options: ["2 centuries", "20 centuries", "200 centuries", "2,000 centuries"], answer: 1, explain: "2025 − 25 = 2000 years, and 2000 ÷ 100 = 20 centuries.", level: 3 }
    ],
    written: [
      { q: "What is meant by the year 500 BCE?", a: "500 BCE means 500 years before the start of the Common Era (Before Common Era). BCE years are counted backwards.", marks: 1 },
      { q: "What is an inscription?", a: "An inscription is writing carved on stone, metal or clay. Historians use it to learn the names of rulers and dates.", marks: 1 },
      { q: "Differentiate between prehistory and history.", a: "1. Prehistory is the period before writing was invented, so there are no written records.\n2. History is the period after writing began, so written sources are available along with other evidence.", marks: 2 },
      { q: "Give two examples of archaeological sources and two examples of literary sources.", a: "Archaeological sources: coins and pots (also tools, seals, ornaments, buildings).\nLiterary sources: the Vedas and royal records (also letters and religious books).", marks: 2 },
      { q: "Why must a historian think about who wrote a source and why it was written?", a: "1. The writer may have shown only one side or praised someone, so the source may be biased.\n2. Knowing who wrote it and why helps the historian decide how far it can be trusted, and compare it with other sources.", marks: 2 },
      { q: "Describe the three kinds of sources that historians use to learn about the past.", a: "1. Archaeological sources are objects and remains such as tools, pots, coins, seals, buildings and inscriptions found by excavation.\n2. Literary (written) sources are texts such as the Vedas, royal records, letters and religious books.\n3. Oral sources are stories, songs and memories passed on by word of mouth from one generation to the next.", marks: 3 },
      { q: "Arrange these years on a timeline from the earliest to the latest: 200 CE, 400 BCE, 100 BCE, 50 CE. Explain how BCE years are counted.", a: "Order: 400 BCE, 100 BCE, 50 CE, 200 CE.\nBCE years are counted backwards, so a bigger BCE number means a time further in the past (400 BCE is earlier than 100 BCE).\nAll CE years come after the BCE years.", marks: 3 },
      { q: "Case study: A farmer digs a well and finds clay pots, an old coin and a stone slab with carved letters. His grandmother also knows a song about an old king that she learnt from her own grandmother.\n(i) Which of the things found are archaeological sources?\n(ii) What is the carved writing on the slab called?\n(iii) What kind of source is the grandmother's song, and why should a historian use it carefully?", a: "(i) The clay pots, the coin and the stone slab.\n(ii) It is an inscription.\n(iii) It is an oral source. It was passed on by word of mouth, so it may have changed or be biased, and a historian should compare it with other sources.", marks: 4, type: "case" }
    ]
  },
  "india-that-is-bharat": {
    mcq: [
      { q: "Which water body lies to the east of India?", options: ["Arabian Sea", "Red Sea", "Bay of Bengal", "Caspian Sea"], answer: 2, explain: "The Bay of Bengal lies to the east of India. The Arabian Sea lies to the west.", level: 1 },
      { q: "Which ancient name for our land is found in texts like the Vishnu Purana?", options: ["India", "Bharat", "Hindustan", "Indus"], answer: 1, explain: "Bharat is an ancient name, linked to the descendants of King Bharata.", level: 1 },
      { q: "What did the Greeks call the land around the river Indus?", options: ["Bharat", "Hindustan", "Sindhu", "India"], answer: 3, explain: "The Greeks used a form of the word Indus and called the land India.", level: 1 },
      { q: "In which part of India does the Thar Desert lie?", options: ["West", "East", "South", "North-east"], answer: 0, explain: "The Thar Desert lies in the west of India.", level: 1 },
      { q: "Which of these countries shares a land border with India?", options: ["Sri Lanka", "Japan", "Nepal", "Maldives"], answer: 2, explain: "Nepal shares a land border with India. Sri Lanka and the Maldives are island countries, and Japan is far away.", level: 1 },
      { q: "Which natural region lies in the middle of India?", options: ["Indo-Gangetic Plains", "Himalayas", "Peninsular Plateau", "Thar Desert"], answer: 0, explain: "The Indo-Gangetic Plains lie in the middle, between the Himalayas in the north and the Peninsular Plateau in the south.", level: 2 },
      { q: "Assertion (A): Southern India is called a peninsula.\nReason (R): It has water on three sides.", options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."], answer: 0, explain: "A peninsula is land surrounded by water on three sides. Southern India has the Arabian Sea, the Indian Ocean and the Bay of Bengal around it, so R explains A.", level: 2, keepOrder: true },
      { q: "Anil travels by train from the foothills of the mountains in the north of India to the south of the country.\nWhich regions does he cross, in order?", options: ["Peninsular Plateau, Indo-Gangetic Plains, Himalayas", "Indo-Gangetic Plains, Himalayas, Peninsular Plateau", "Himalayas, Peninsular Plateau, Indo-Gangetic Plains", "Himalayas, Indo-Gangetic Plains, Peninsular Plateau"], answer: 3, explain: "From north to south the regions are the Himalayas, the Indo-Gangetic Plains and the Peninsular Plateau.", level: 2 },
      { q: "Sara reads Article 1 of the Constitution, which says 'India, that is Bharat, shall be a Union of States'. She wonders which name is correct.\nWhat is the right answer?", options: ["Only 'India' is official", "Both 'India' and 'Bharat' are used officially", "Only 'Bharat' is official", "Neither name is official"], answer: 1, explain: "The Constitution itself uses both names, 'India, that is Bharat', so both are official.", level: 2 },
      { q: "Which description of India's surroundings is correct?", options: ["Arabian Sea to the east, Bay of Bengal to the west", "Bay of Bengal to the south, Indian Ocean to the north", "Arabian Sea to the west, Bay of Bengal to the east, Indian Ocean to the south", "Arabian Sea to the north, Indian Ocean to the east"], answer: 2, explain: "The Arabian Sea is on the west, the Bay of Bengal is on the east, and the Indian Ocean lies to the south of the peninsula.", level: 2 },
      { q: "Which statement correctly matches each name of the land with its origin?", options: ["India from Greek, Hindu from Persian, Bharat from Chinese", "India from Persian, Hindu from Greek, Bharat from the Vishnu Purana", "India from Greeks' form of Indus, Hindu from Persians' way of saying Sindhu, Bharat from ancient texts", "India from the Bay of Bengal, Hindu from the Thar, Bharat from the Ganga"], answer: 2, explain: "Greeks used a form of Indus (India). Persians pronounced Sindhu as Hindu. Bharat is an ancient name found in texts such as the Vishnu Purana.", level: 3 },
      { q: "A friend says, 'Everyone in India eats the same food and wears the same clothes.'\nWhich fact from the lesson shows she is wrong?", options: ["India is a very small country", "India has no variety of landforms", "India has many different landforms, climates and vegetation, which affect food, clothes and crops", "India has only one festival"], answer: 2, explain: "Variety in landforms, climate and vegetation affects what people eat and wear, the crops they grow and the festivals they celebrate.", level: 3 },
      { q: "Which group contains only land neighbours of India?", options: ["Nepal, Bhutan, Myanmar, Bangladesh", "Nepal, Sri Lanka, Bhutan, China", "Pakistan, Maldives, Nepal, Bhutan", "China, Myanmar, Sri Lanka, Bangladesh"], answer: 0, explain: "Nepal, Bhutan, Myanmar and Bangladesh all share land borders with India. Sri Lanka and the Maldives are islands across the sea.", level: 3 },
      { q: "A ship sails from a port on the Arabian Sea to a port on the Bay of Bengal by going around the southern end of the peninsula.\nWhich large water body does it pass through on the way?", options: ["Pacific Ocean", "Indian Ocean", "Red Sea", "Arctic Ocean"], answer: 1, explain: "The Indian Ocean lies to the south of the peninsula, so the ship must cross it to go from the Arabian Sea to the Bay of Bengal.", level: 3 }
    ],
    written: [
      { q: "Which river gave its name to the word 'India'?", a: "The river Sindhu (Indus) gave its name to the word 'India' (through the Greek form of the name).", marks: 1 },
      { q: "Name the sea to the east of India and the sea to the west of India.", a: "The Bay of Bengal lies to the east and the Arabian Sea lies to the west.", marks: 1 },
      { q: "Write two names of our country and say where each name comes from.", a: "1. India comes from the Greek form of Indus (Sindhu), the river in the north-west.\n2. Bharat is an ancient name found in texts such as the Vishnu Purana, linked to King Bharata's descendants.", marks: 2 },
      { q: "Name any four land neighbours of India.", a: "Pakistan, China, Nepal, Bhutan, Bangladesh and Myanmar (any four).", marks: 2 },
      { q: "What is the difference between a land neighbour and an island neighbour of India? Give one example of each.", a: "1. A land neighbour shares a land border with India, for example Nepal.\n2. An island neighbour is across the sea and has no land border with India, for example Sri Lanka.", marks: 2 },
      { q: "Describe the three main natural regions of India.", a: "1. The Himalayas lie in the north.\n2. The Indo-Gangetic Plains lie in the middle.\n3. The Peninsular Plateau lies in the south.", marks: 3 },
      { q: "How does the variety of landforms and climates in India affect the lives of people?", a: "1. India has many landforms, climates and types of vegetation.\n2. This variety affects the food people eat, the clothes they wear and the crops they grow.\n3. It also affects the festivals they celebrate.", marks: 3 },
      { q: "Case study: Anita looks at a map of India. She sees high mountains in the north, a wide flat land in the middle, and a raised land in the south that has water on three sides. She also notices a sea on the west and another on the east.\n(i) Name the mountains in the north.\n(ii) What is land surrounded by water on three sides called?\n(iii) Name the sea on the west and the sea on the east.", a: "(i) The Himalayas.\n(ii) A peninsula.\n(iii) The Arabian Sea is on the west and the Bay of Bengal is on the east.", marks: 4, type: "case" }
    ]
  },
  "beginnings-of-indian-civilisation": {
    mcq: [
      { q: "In which age did people hunt animals and gather fruits and roots using rough stone tools?", options: ["Neolithic Age", "Palaeolithic Age", "Mesolithic Age", "Harappan Age"], answer: 1, explain: "The Palaeolithic (Old Stone) Age was the time of hunter-gatherers using rough stone tools.", level: 1 },
      { q: "In which state are the Bhimbetka rock shelters?", options: ["Gujarat", "Rajasthan", "Punjab", "Madhya Pradesh"], answer: 3, explain: "The Bhimbetka rock shelters, with their ancient paintings, are in Madhya Pradesh.", level: 1 },
      { q: "In which present-day country are Harappa and Mohenjo-daro?", options: ["India", "Nepal", "Pakistan", "Bhutan"], answer: 2, explain: "Harappa and Mohenjo-daro are in present-day Pakistan.", level: 1 },
      { q: "Which of these Harappan sites is in present-day India?", options: ["Dholavira", "Mohenjo-daro", "Harappa", "Bhimbetka"], answer: 0, explain: "Dholavira is in India, along with Lothal and Kalibangan. Bhimbetka is a Stone Age rock shelter, not a Harappan town.", level: 1 },
      { q: "Houses in Harappan towns were built of", options: ["wood only", "straw only", "stone slabs", "baked bricks"], answer: 3, explain: "Harappan houses were built of baked bricks.", level: 1 },
      { q: "Finer stone tools and the beginning of taming some animals belong to which age?", options: ["Palaeolithic", "Neolithic", "Mesolithic", "Iron Age"], answer: 2, explain: "In the Mesolithic (Middle Stone) Age people made finer tools and began to tame some animals. Farming and villages came in the Neolithic Age.", level: 2 },
      { q: "What were seals used for in Harappan towns?", options: ["To cut grain", "To stamp or mark goods in trade", "To play games", "To make bricks"], answer: 1, explain: "Seals were small carved objects used for trade, to mark ownership or stamp goods.", level: 2 },
      { q: "Assertion (A): Harappan towns were well planned.\nReason (R): They had grid-like streets and covered drains.", options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."], answer: 0, explain: "Streets laid out in a grid and covered drains show that the towns were carefully planned, so R explains A.", level: 2, keepOrder: true },
      { q: "Archaeologists uncover a settlement with streets in a grid, houses of baked bricks and covered drains.\nWhich settlement is most likely to be this?", options: ["A Palaeolithic camp", "A Neolithic farming hamlet", "A Mesolithic cave", "A Harappan town"], answer: 3, explain: "Grid-like streets, baked-brick houses and covered drains are signs of a planned Harappan town.", level: 2 },
      { q: "Kabir visits the Bhimbetka caves and sees paintings of animals, hunts and dances.\nWhat do such paintings help historians learn?", options: ["How to make baked bricks", "The names of kings", "The daily life and beliefs of early people", "The Harappan script"], answer: 2, explain: "Rock paintings show what early people did and believed, such as hunting and dancing.", level: 2 },
      { q: "The mature phase of the Harappan civilisation lasted from about 2600 BCE to 1900 BCE. For about how many years did it last?", options: ["600 years", "700 years", "800 years", "2,600 years"], answer: 1, explain: "Both dates are BCE, so subtract: 2600 − 1900 = 700 years.", level: 3 },
      { q: "Which pair of finds best shows that the Harappan economy was well organised?", options: ["Rock paintings and stone tools", "Hunting scenes and caves", "Large granaries and standard weights", "Cave paintings and burnt wood"], answer: 2, explain: "Large granaries for storing grain and standard weights for trade show careful organisation.", level: 3 },
      { q: "Why do historians still have many unanswered questions about the Harappan people's beliefs and rulers?", options: ["Their script has not yet been deciphered", "They left no objects behind", "Their towns have never been dug up", "They did not build any houses"], answer: 0, explain: "Many objects and towns have been found, but the Harappan script cannot be read yet, so much remains unknown.", level: 3 },
      { q: "Which statement about the end of the Harappan civilisation is correct?", options: ["It ended in 2600 BCE for a known reason", "Its script tells us exactly why it ended", "It was still growing after 1000 BCE", "It declined after about 1900 BCE, and the reasons are still debated"], answer: 3, explain: "The civilisation declined after about 1900 BCE. Historians still debate the reasons.", level: 3 }
    ],
    written: [
      { q: "How did people get their food in the Palaeolithic Age?", a: "They hunted animals and gathered fruits and roots, using rough stone tools.", marks: 1 },
      { q: "Where are the Bhimbetka rock shelters located?", a: "The Bhimbetka rock shelters are located in Madhya Pradesh.", marks: 1 },
      { q: "What were seals? How were they used by the Harappan people?", a: "1. Seals were small carved stone or clay objects.\n2. They were used in trade, to mark ownership or to stamp goods.", marks: 2 },
      { q: "Why do historians value the rock paintings at places like Bhimbetka?", a: "1. They show animals, hunts and dances made thousands of years ago.\n2. They help historians learn about the daily life and beliefs of early people.", marks: 2 },
      { q: "Write two differences between life in the Palaeolithic Age and life in the Neolithic Age.", a: "1. In the Palaeolithic Age people hunted and gathered food; in the Neolithic Age they began farming and rearing animals.\n2. Palaeolithic people used rough stone tools and kept moving; Neolithic people settled in villages.", marks: 2 },
      { q: "Describe the main features of a Harappan town.", a: "1. The streets were laid out in a grid.\n2. Houses were built of baked bricks, and the drains were covered.\n3. Some towns had special buildings, such as the Great Bath at Mohenjo-daro and large granaries.", marks: 3 },
      { q: "What do large granaries, standard weights and seals tell us about the Harappan economy?", a: "1. Large granaries show that grain was stored carefully.\n2. Standard weights show that trade and exchange were organised.\n3. Seals were used in trade, and the Harappans traded with distant lands, including Mesopotamia.", marks: 3 },
      { q: "Case study: Archaeologists uncover a town with straight streets in a grid, houses of baked bricks and covered drains. They find a big storehouse for grain, many small carved stones used as seals, and some writing that nobody can yet read.\n(i) Name two Harappan sites in India.\n(ii) What is the storehouse for grain called?\n(iii) Why can historians not yet read the writing?", a: "(i) Any two of Lothal, Dholavira and Kalibangan.\n(ii) A granary.\n(iii) The Harappan script has not yet been deciphered.", marks: 4, type: "case" }
    ]
  },
  "indias-cultural-roots": {
    mcq: [
      { q: "In which language were the Vedas composed?", options: ["Tamil", "Sanskrit", "Pali", "Prakrit"], answer: 1, explain: "The Vedas were composed in Sanskrit.", level: 1 },
      { q: "About how old are the Sangam poems?", options: ["200 years", "20,000 years", "2,000 years", "500 years"], answer: 2, explain: "The Sangam poems of Tamil literature are about 2,000 years old.", level: 1 },
      { q: "Carnatic music is the classical music tradition of", options: ["Northern India", "Southern India", "Western Asia", "Eastern Africa"], answer: 1, explain: "Carnatic music belongs to the south, while Hindustani music belongs to the north.", level: 1 },
      { q: "The Ajanta and Ellora caves are famous for", options: ["ancient paintings and sculptures in rock", "tall brick walls of Harappan towns", "Harappan granaries", "Neolithic farms"], answer: 0, explain: "Ajanta and Ellora have ancient paintings and sculptures carved into rock.", level: 1 },
      { q: "Which languages did Buddhist and Jain teachers use to spread their messages?", options: ["Greek and Latin", "Persian and Arabic", "Sanskrit and English", "Pali and Prakrit"], answer: 3, explain: "Pali and Prakrit were used by Buddhist and Jain teachers.", level: 1 },
      { q: "Who wrote an ancient text on surgery?", options: ["Charaka", "Aryabhata", "Brahmagupta", "Sushruta"], answer: 3, explain: "Sushruta wrote on surgery. Charaka wrote on medicine.", level: 2 },
      { q: "Who explained the rules for using zero in calculations in the 7th century CE?", options: ["Aryabhata", "Sushruta", "Brahmagupta", "Guru Nanak"], answer: 2, explain: "Brahmagupta explained rules for using zero in the 7th century CE.", level: 2 },
      { q: "Assertion (A): The Vedas were passed on by word of mouth for many generations.\nReason (R): The Vedas were composed in Sanskrit.", options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."], answer: 1, explain: "Both statements are true. But the language, Sanskrit, is not the reason they were passed on by mouth, so R does not explain A.", level: 2, keepOrder: true },
      { q: "Riya, a student in Delhi, enjoys listening to the classical music of northern India.\nWhich tradition is it?", options: ["Hindustani music", "Carnatic music", "Sangam music", "Folk music of the south"], answer: 0, explain: "Hindustani music is the classical tradition of northern India.", level: 2 },
      { q: "For a quiz, Imran has to name the thinker of the 5th century CE who proposed that the Earth turns on its own axis.\nWhom should he name?", options: ["Charaka", "Brahmagupta", "Aryabhata", "Sushruta"], answer: 2, explain: "Aryabhata, who wrote on mathematics and astronomy in the 5th century CE, proposed that the Earth turns on its axis.", level: 2 },
      { q: "Which list contains only classical dance forms?", options: ["Bhangra, Gidda, Kathak, Odissi", "Bharatanatyam, Kathak, Odissi, Kuchipudi", "Kathak, Lavani, Manipuri, Gidda", "Bhangra, Lavani, Kuchipudi, Kathakali"], answer: 1, explain: "Bharatanatyam, Kathak, Odissi and Kuchipudi are all classical dances. Bhangra, Gidda and Lavani are folk dances.", level: 3 },
      { q: "Which is a correct match of a person with the field of work?", options: ["Charaka – astronomy", "Sushruta – zero", "Aryabhata – surgery", "Charaka – medicine"], answer: 3, explain: "Charaka wrote on medicine. Sushruta wrote on surgery, Aryabhata on mathematics and astronomy, and Brahmagupta on rules for zero.", level: 3 },
      { q: "Aryabhata lived in the 5th century CE and Brahmagupta in the 7th century CE.\nHow many centuries later did Brahmagupta live?", options: ["2 centuries", "12 centuries", "20 centuries", "7 centuries"], answer: 0, explain: "7th century minus 5th century = 2 centuries.", level: 3 },
      { q: "Which statement is correct?", options: ["Sikhism was founded in the 6th century BCE", "The Sangam poems were composed in Sanskrit", "Hindustani music is the classical tradition of the south", "Buddhism and Jainism arose around the 6th century BCE and both teach ahimsa"], answer: 3, explain: "Buddhism and Jainism arose around the 6th century BCE and both teach non-violence (ahimsa). Sikhism was founded in the 15th century, the Sangam poems are in Tamil, and Hindustani music belongs to the north.", level: 3 }
    ],
    written: [
      { q: "In which language were the Vedas composed?", a: "The Vedas were composed in Sanskrit.", marks: 1 },
      { q: "Name the two main traditions of Indian classical music.", a: "Hindustani music (north) and Carnatic music (south).", marks: 1 },
      { q: "Who were Charaka and Sushruta? What did each write about?", a: "1. Charaka was an ancient scholar who wrote on medicine.\n2. Sushruta was an ancient scholar who wrote on surgery.", marks: 2 },
      { q: "Name any four classical dance forms of India.", a: "Bharatanatyam, Kathak, Odissi, Kuchipudi, Kathakali, Manipuri, Mohiniyattam and Sattriya (any four).", marks: 2 },
      { q: "What is ahimsa? Name two traditions that teach it.", a: "Ahimsa means non-violence.\nBuddhism and Jainism both teach non-violence and compassion.", marks: 2 },
      { q: "Write three contributions of Aryabhata and Brahmagupta to knowledge.", a: "1. Aryabhata (5th century CE) wrote on mathematics and astronomy.\n2. Aryabhata proposed that the Earth turns on its own axis.\n3. Brahmagupta (7th century CE) explained the rules for using zero in calculations.", marks: 3 },
      { q: "Describe the ancient texts and languages that form part of India's cultural roots.", a: "1. The Vedas are among the oldest texts, composed in Sanskrit and passed on by word of mouth for many generations.\n2. Tamil has a rich literature, including the Sangam poems, which are about 2,000 years old.\n3. Pali and Prakrit were used by Buddhist and Jain teachers to spread their messages.", marks: 3 },
      { q: "Case study: Priya visits the Ajanta and Ellora caves, where she sees paintings and sculptures carved into rock. Her teacher then tells her that classical music has one tradition in the north and another in the south, and that the Sangam poems are very old.\n(i) Which cave sites did Priya visit?\n(ii) Name the classical music traditions of the north and the south.\n(iii) In which language are the Sangam poems, and about how old are they?", a: "(i) The Ajanta and Ellora caves.\n(ii) Hindustani music in the north and Carnatic music in the south.\n(iii) They are in Tamil and are about 2,000 years old.", marks: 4, type: "case" }
    ]
  }
});
